import fs from 'fs';
import path from 'path';
import { fatal, warn, info } from '../utils/logger.js';
import { ROOT_FILES, MODULE_ROOT, moduleDirs, nestableDirs } from './project-layout.js';
import { wdPath, displayPath } from './workdir.js';

/**
 * Module paths (relative to the module root, with `.js`) of all project files:
 * the root files plus every `*.js` under the module directories. Fatal if a
 * non-nestable directory contains subdirectories.
 */
export function scanFiles() {
  const files = [];
  const nestable = nestableDirs();

  for (const rootFile of ROOT_FILES) {
    if (fs.existsSync(wdPath(rootFile))) {
      files.push(rootFile);
    }
  }

  for (const dir of moduleDirs()) {
    if (!fs.existsSync(wdPath(dir))) continue;
    walkJs(dir, dir, files, nestable);
  }

  // POSIX separators, so paths match the snapshot and the wire on Windows.
  return files.map((f) => f.split(/[\\/]/).join('/'));
}

// `currentDir` is a module path; collected paths stay module-relative.
function walkJs(currentDir, baseDir, out, nestable) {
  for (const entry of fs.readdirSync(wdPath(currentDir), { withFileTypes: true })) {
    const rel = path.join(currentDir, entry.name);
    if (entry.isDirectory()) {
      if (!nestable.has(baseDir)) {
        fatal(
          `${displayPath(baseDir)}/ must be flat — found subdirectory ${displayPath(rel)}. ` +
          `Only ${[...nestable].map((d) => displayPath(d) + '/').join(', ')} allow nested modules.`
        );
      }
      walkJs(rel, baseDir, out, nestable);
    } else if (entry.isFile() && entry.name.endsWith('.js')) {
      out.push(rel);
    }
  }
}

/**
 * `*.js` inside the module root that the scanner does not pick up (not a root
 * file, or under a non-module directory); they are never deployed. Dotfiles
 * are skipped. Returns display paths.
 */
export function findStrayFiles() {
  const rootFiles = new Set(ROOT_FILES);
  const dirs = new Set(moduleDirs());
  let entries;
  try {
    entries = fs.readdirSync(MODULE_ROOT, { withFileTypes: true });
  } catch {
    return [];
  }
  const out = [];
  for (const entry of entries) {
    if (entry.name.startsWith('.')) continue;
    if (entry.isFile()) {
      if (entry.name.endsWith('.js') && !rootFiles.has(entry.name)) out.push(displayPath(entry.name));
    } else if (entry.isDirectory() && !dirs.has(entry.name)) {
      collectJs(entry.name, out);
    }
  }
  return out;
}

function collectJs(rel, out) {
  let entries;
  try {
    entries = fs.readdirSync(wdPath(rel), { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    const child = path.join(rel, entry.name);
    if (entry.isDirectory()) collectJs(child, out);
    else if (entry.isFile() && entry.name.endsWith('.js')) out.push(displayPath(child));
  }
}

/** Warn about stray `.js` files in the module root. Returns the strays. */
export function warnStrayFiles() {
  const strays = findStrayFiles();
  if (!strays.length) return strays;
  info('');
  warn(
    `${strays.length} stray .js file${strays.length === 1 ? '' : 's'} in ` +
    `${MODULE_ROOT}/ will not be deployed:`
  );
  for (const f of strays) info(`  ${f}`);
  const dirs = moduleDirs().map((d) => displayPath(d) + '/').join(', ');
  info(`Move ${strays.length === 1 ? 'it' : 'them'} into a module directory (${dirs}) to deploy.`);
  return strays;
}
